window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c42f7b365f902f4f"]={"versions": [{"id": "FIG-c42f7b365f902f4f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-basiertes Prozess- und Methodikdiagramm (Activity / Task Use Diagram) im Kontext des AUTOSAR-Standardization-Templates (TPS Standardization Template). Das Diagramm visualisiert die organisatorische und methodische Definition von Datentypen für Basissoftware-Module (BSW Types) anhand von standardisierten Vorgaben (Blueprints).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rollen (Roles)</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code>: Rolle, die die Aktivität ausführt (Assoziation <code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><code>Basic Software Module Developer</code>: Rolle, die optional an der Ausführung beteiligt ist (Assoziation <code>«performs»</code>, Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Aktivität / Prozessschritt (Task Definition)</strong>:\n<ul class=\"fig-list\"><li><code>Define BSW Types</code>: Zentraler Prozessschritt zur Festlegung und Ausprägung der BSW-Datentypen.\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>BSW Standard Package</code>: Eingangspaket mit standardisierten AUTOSAR-Blueprints (Stereotyp <code>«input»</code>, Kardinalität <code>0..1</code>).\n</li><li><code>BSW Types</code>: Ausgangs- bzw. Modifikationsartefakt der Typdefinitionen (gerichtete Kante mit doppeltem Pfeil/Stereotyp <code>«inoutput»</code>, Kardinalität <code>0..1</code> am Ausgang der Aktivität).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Basic Software Designer</code> initiiert und leitet verbindlich die Aktivität <code>Define BSW Types</code> an (Multiplizität 1).\n</li><li>Optional wird der <code>Basic Software Module Developer</code> in den Bearbeitungsschritt eingebunden (Multiplizität 0..1).\n</li><li>Die Aktivität konsumiert optional Vorgaben aus dem <code>BSW Standard Package</code> (<code>«input»</code>, 0..1).\n</li><li>Als Ergebnis werden die <code>BSW Types</code> erzeugt oder ein bestehender Stand weiterentwickelt (<code>«inoutput»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß TPS_STDT_00067 müssen Objekte, die aus standardisierten Blueprints abgeleitet werden, der vorgegebenen Paketstruktur folgen (z. B. Überführung von <code>/AUTOSAR/Platform/ImplementationDatatypes_Blueprint/...</code> in <code>/AUTOSAR_Platform/ImplementationDatatypes/...</code>). Dies gewährleistet, dass Basissoftware-Entwickler und Komponentenanbieter über deterministische Paketpfade auf die standardisierten Typdefinitionen zugreifen können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0b798dc30f2f9c05", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-basiertes Prozess- und Methodikdiagramm (Activity / Task Use Diagram) im Kontext des AUTOSAR-Standardization-Templates (TPS Standardization Template). Das Diagramm visualisiert die organisatorische und methodische Definition von Datentypen für Basissoftware-Module (BSW Types) anhand von standardisierten Vorgaben (Blueprints).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rollen (Roles)</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code>: Rolle, die die Aktivität ausführt (Assoziation <code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><code>Basic Software Module Developer</code>: Rolle, die optional an der Ausführung beteiligt ist (Assoziation <code>«performs»</code>, Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Aktivität / Prozessschritt (Task Definition)</strong>:\n<ul class=\"fig-list\"><li><code>Define BSW Types</code>: Zentraler Prozessschritt zur Festlegung und Ausprägung der BSW-Datentypen.\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>BSW Standard Package</code>: Eingangspaket mit standardisierten AUTOSAR-Blueprints (Stereotyp <code>«input»</code>, Kardinalität <code>0..1</code>).\n</li><li><code>BSW Types</code>: Ausgangs- bzw. Modifikationsartefakt der Typdefinitionen (gerichtete Kante mit doppeltem Pfeil/Stereotyp <code>«inoutput»</code>, Kardinalität <code>0..1</code> am Ausgang der Aktivität).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Basic Software Designer</code> initiiert und leitet verbindlich die Aktivität <code>Define BSW Types</code> an (Multiplizität 1).\n</li><li>Optional wird der <code>Basic Software Module Developer</code> in den Bearbeitungsschritt eingebunden (Multiplizität 0..1).\n</li><li>Die Aktivität konsumiert optional Vorgaben aus dem <code>BSW Standard Package</code> (<code>«input»</code>, 0..1).\n</li><li>Als Ergebnis werden die <code>BSW Types</code> erzeugt oder ein bestehender Stand weiterentwickelt (<code>«inoutput»</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß TPS_STDT_00067 müssen Objekte, die aus standardisierten Blueprints abgeleitet werden, der vorgegebenen Paketstruktur folgen (z. B. Überführung von <code>/AUTOSAR/Platform/ImplementationDatatypes_Blueprint/...</code> in <code>/AUTOSAR_Platform/ImplementationDatatypes/...</code>). Dies gewährleistet, dass Basissoftware-Entwickler und Komponentenanbieter über deterministische Paketpfade auf die standardisierten Typdefinitionen zugreifen können.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c42f7b365f902f4f", "to": "FIG-0b798dc30f2f9c05", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
